import{_ as e,o,c as a,a2 as n}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Copilot — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"copilot-01-overview-and-concepts.md","filePath":"copilot-01-overview-and-concepts.md"}'),r={name:"copilot-01-overview-and-concepts.md"};function i(s,t,d,l,c,u){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="copilot-—-overview-concepts" tabindex="-1">Copilot — Overview &amp; Concepts <a class="header-anchor" href="#copilot-—-overview-concepts" aria-label="Permalink to &quot;Copilot — Overview &amp; Concepts&quot;">​</a></h1><p><em>What it is, how it works, and what it can do for you</em></p><hr><h2 id="what-is-copilot" tabindex="-1">What Is Copilot? <a class="header-anchor" href="#what-is-copilot" aria-label="Permalink to &quot;What Is Copilot?&quot;">​</a></h2><p>Copilot is Lodestone&#39;s built-in AI assistant. It&#39;s accessible from anywhere in the platform through the <strong>Copilot</strong> button in the left-hand navigation. It helps you in two ways: answering questions about Lodestone and product management, and taking actions directly in your workspace — creating features, building roadmaps, generating documents — on your behalf.</p><p>Copilot is not a general-purpose chatbot. It knows your workspace, understands Lodestone&#39;s modules, and can act on your data. The difference from a typical AI chat tool is that Copilot is wired into the platform — it can see your features, your roadmaps, your releases, and it can make changes when you ask it to.</p><hr><h2 id="how-to-access-copilot" tabindex="-1">How to Access Copilot <a class="header-anchor" href="#how-to-access-copilot" aria-label="Permalink to &quot;How to Access Copilot&quot;">​</a></h2><p>Click <strong>Copilot</strong> in the left-hand navigation. A chat panel opens on top of the current page. You can close it at any time and return to whatever you were doing — the panel is non-destructive and doesn&#39;t navigate away from your current view.</p><p>Copilot is available from every module in Lodestone. You don&#39;t need to navigate to a special page to use it.</p><hr><h2 id="two-modes" tabindex="-1">Two Modes <a class="header-anchor" href="#two-modes" aria-label="Permalink to &quot;Two Modes&quot;">​</a></h2><p>Copilot automatically detects what kind of help you need and routes your message to the appropriate mode. You don&#39;t choose the mode manually.</p><h3 id="chatbot-mode" tabindex="-1">Chatbot Mode <a class="header-anchor" href="#chatbot-mode" aria-label="Permalink to &quot;Chatbot Mode&quot;">​</a></h3><p>Used when you ask a question or want to learn something.</p><ul><li>&quot;How does the RICE scoring framework work?&quot;</li><li>&quot;What&#39;s the difference between a Roadmap and a Strategy?&quot;</li><li>&quot;How do I connect Gong to Lodestone?&quot;</li><li>&quot;What should I include in a PRD?&quot;</li></ul><p>In Chatbot mode, Copilot draws from Lodestone&#39;s knowledge base (platform guides, tutorials, FAQs) and product management best practices (RICE, user stories, frameworks, templates) to give you accurate, contextual answers.</p><h3 id="agentic-mode" tabindex="-1">Agentic Mode <a class="header-anchor" href="#agentic-mode" aria-label="Permalink to &quot;Agentic Mode&quot;">​</a></h3><p>Used when you ask Copilot to do something.</p><ul><li>&quot;Create a feature called Single Sign-On&quot;</li><li>&quot;Add that feature to my Q3 Roadmap&quot;</li><li>&quot;Generate a PRD for the SSO feature&quot;</li><li>&quot;Show me all features that are In Progress&quot;</li><li>&quot;Create a release called v2.1&quot;</li></ul><p>In Agentic mode, Copilot uses tools connected to your workspace to carry out the requested action. It returns a confirmation of what it did, including links where relevant. All actions respect your current role and permissions — Copilot cannot do things you couldn&#39;t do yourself.</p><hr><h2 id="what-copilot-can-do" tabindex="-1">What Copilot Can Do <a class="header-anchor" href="#what-copilot-can-do" aria-label="Permalink to &quot;What Copilot Can Do&quot;">​</a></h2><h3 id="questions-and-guidance-chatbot-mode" tabindex="-1">Questions and guidance (Chatbot mode) <a class="header-anchor" href="#questions-and-guidance-chatbot-mode" aria-label="Permalink to &quot;Questions and guidance (Chatbot mode)&quot;">​</a></h3><ul><li>Explain any Lodestone feature or concept</li><li>Answer product management questions (frameworks, best practices, templates)</li><li>Help you understand the difference between modules or decide which to use</li></ul><h3 id="actions-on-your-workspace-agentic-mode" tabindex="-1">Actions on your workspace (Agentic mode) <a class="header-anchor" href="#actions-on-your-workspace-agentic-mode" aria-label="Permalink to &quot;Actions on your workspace (Agentic mode)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Example</th></tr></thead><tbody><tr><td>List backlog items</td><td>&quot;Show me all features with status In Progress&quot;</td></tr><tr><td>Create a feature</td><td>&quot;Create a feature called Offline Mode&quot;</td></tr><tr><td>Update a feature</td><td>&quot;Set the SSO feature to In Progress&quot;</td></tr><tr><td>Create a Roadmap</td><td>&quot;Create a roadmap called Q4 2026&quot;</td></tr><tr><td>Add a feature to a Roadmap</td><td>&quot;Add SSO to the Q4 roadmap&quot;</td></tr><tr><td>List Roadmaps</td><td>&quot;What roadmaps do I have?&quot;</td></tr><tr><td>Create a Release</td><td>&quot;Create a release called v2.1&quot;</td></tr><tr><td>List Releases</td><td>&quot;What releases are active?&quot;</td></tr><tr><td>Create a Strategy</td><td>&quot;Create a strategy called Platform 2027&quot;</td></tr><tr><td>List Strategies</td><td>&quot;Show me my strategies&quot;</td></tr><tr><td>Generate documents</td><td>&quot;Generate a PRD for the SSO feature&quot;</td></tr></tbody></table><hr><h2 id="what-copilot-cannot-do" tabindex="-1">What Copilot Cannot Do <a class="header-anchor" href="#what-copilot-cannot-do" aria-label="Permalink to &quot;What Copilot Cannot Do&quot;">​</a></h2><p>Copilot works within the same permissions you have. It cannot:</p><ul><li>Access data in other organizations you are not a member of</li><li>Delete features, roadmaps, or other objects (as of current version)</li><li>Take actions outside of Lodestone (it is not connected to JIRA, Gong, or other external tools)</li><li>Access or reference quotes, evaluation scores, or financial models in responses (it reads backlog items and planning objects, not all sub-objects)</li></ul><hr><h2 id="conversation-persistence" tabindex="-1">Conversation Persistence <a class="header-anchor" href="#conversation-persistence" aria-label="Permalink to &quot;Conversation Persistence&quot;">​</a></h2><p>Copilot remembers the context of your current conversation as you chat — you can refer back to things earlier in the exchange (&quot;do that again&quot;, &quot;now add it to the roadmap we just created&quot;) and Copilot will understand. This context is maintained within the conversation session.</p><hr><p><em>Next: How-tos &amp; Workflows — using Copilot effectively for common tasks.</em></p>',36)])])}const m=e(r,[["render",i]]);export{p as __pageData,m as default};
